use coaptic::{App, Code, Endpoint, Response, get, resources};
use coaptic::message::{Type, decode};
use coaptic::storage::{DatagramIo, DatagramTransport};
use std::time::Instant;

const BODY: [u8; 2000] = {
    let mut bytes = [0; 2000];
    let mut i = 0;
    while i < bytes.len() { bytes[i] = (i % 251) as u8; i += 1; }
    bytes
};
const PEER: Endpoint = Endpoint::v4([192,0,2,1],5683);

struct Wire { packet: [u8; 9], len: usize, armed: bool, sent: usize }
impl DatagramTransport for Wire { type Error = (); }
impl DatagramIo for Wire {
    fn recv(&mut self, out: &mut [u8]) -> Result<Option<(usize, Endpoint)>, ()> {
        if !std::mem::take(&mut self.armed) {return Ok(None);}
        out[..self.len].copy_from_slice(&self.packet[..self.len]);
        Ok(Some((self.len, PEER)))
    }
    fn send(&mut self, dest: Endpoint, bytes: &[u8]) -> Result<usize, ()> {
        let p = decode(bytes).unwrap();
        assert_eq!(dest, PEER);
        assert_eq!(p.ty(), Type::Acknowledgement);
        assert_eq!(p.code(), Code::CONTENT);
        assert_eq!(p.message_id().get().to_be_bytes(), self.packet[2..4]);
        assert_eq!(p.token().as_bytes(), &self.packet[4..5]);
        if self.packet[6] == b's' {
            assert_eq!(p.payload(), &BODY[..7]);
            assert!(p.block2().is_none());
        } else {
            let follow = self.len == 9;
            let b = p.block2().unwrap().unwrap();
            assert_eq!(b.num(), u32::from(follow));
            assert_eq!(b.more(), !follow);
            assert_eq!(p.payload(), if follow {&BODY[1024..]} else {&BODY[..1024]});
        }
        self.sent += 1;
        Ok(bytes.len())
    }
}
fn run<const A:usize>(large:bool, n:usize) {
    let app_config = resources::SmallDevice::new().routes::<8>().client_calls::<4>().block_wise::<true>().associations::<A>();
    let wire = Wire {packet:[0x41,1,0,0,0x35,0xb1, if large {b'b'} else {b's'},0xc1,0x16],len:7,armed:false,sent:0};
    let mut app = App::with_resources(app_config).deterministic_for_tests().allow_unprotected()
      .route("s",get(|_| Response::new(Code::CONTENT).payload_borrowed(&BODY[..7])))
      .route("b",get(|_| Response::new(Code::CONTENT).payload_borrowed(&BODY))).bind(wire).unwrap();
    let begin=Instant::now();
    let blocks=if large {2} else {1};
    for index in 0..n {
        for part in 0..blocks {
            let mid=index*blocks+part;
            let sock=app.transport_mut();
            sock.packet[2..4].copy_from_slice(&(mid as u16).to_be_bytes());
            sock.packet[4]=index as u8;
            sock.len=if part==0 {7} else {9};
            sock.armed=true;
            app.poll(mid as u64).unwrap();
        }
    }
    let elapsed=begin.elapsed().as_nanos();
    assert_eq!(app.transport().sent, n*blocks);
    println!("{A} {large} {n} {elapsed}");
}
fn main() {
    let args:Vec<_>=std::env::args().collect();
    let large=&args[2]=="large";
    let n=args[3].parse().unwrap();
    match args[1].as_str() {"1"=>run::<1>(large,n),"32"=>run::<32>(large,n),_=>panic!()}
}

