     #[must_use]
     pub const fn endpoint(self) -> Endpoint {
         self.endpoint
+    }
+}
+
+// Empty control datagrams are four bytes. A TX pin needs no inline packet.
+const CONTROL_BYTES: usize = 4;
+
+// Fixed rows reserve the largest replay at startup regardless of its active variant.
+#[allow(clippy::large_enum_variant)]
+#[derive(Clone, Copy)]
+enum ReplayBytes {
+    Short([u8; CONTROL_BYTES]),
+    Full([u8; DedupEntry::REPLAY_MAX]),
+}
+
+impl ReplayBytes {
+    fn bytes(&self) -> &[u8] {
+        match self {
+            Self::Short(bytes) => bytes,
+            Self::Full(bytes) => bytes,
+        }
+    }
+
+    fn with_full<R>(&self, read: impl FnOnce(&[u8; DedupEntry::REPLAY_MAX]) -> R) -> R {
+        match self {
+            Self::Full(bytes) => read(bytes),
+            Self::Short(short) => {
+                let mut bytes = [0; DedupEntry::REPLAY_MAX];
+                bytes[..CONTROL_BYTES].copy_from_slice(short);
+                read(&bytes)
+            }
+        }
+    }
+
+    fn write(&mut self, bytes: &[u8]) {
+        match self {
+            Self::Short(stored) if bytes.len() <= CONTROL_BYTES => {
+                stored[..bytes.len()].copy_from_slice(bytes);
+            }
+            Self::Short(_) => {
+                let mut stored = [0; DedupEntry::REPLAY_MAX];
+                stored[..bytes.len()].copy_from_slice(bytes);
+                *self = Self::Full(stored);
+            }
+            Self::Full(stored) => stored[..bytes.len()].copy_from_slice(bytes),
+        }
+    }
+}
+
+// The original fixed array retained its tail across shortened replays and pins.
+// Preserve equality and hashing even when a full array has a zero tail.
+impl PartialEq for ReplayBytes {
+    fn eq(&self, other: &Self) -> bool {
+        match (self, other) {
+            (Self::Short(a), Self::Short(b)) => a == b,
+            (Self::Full(a), Self::Full(b)) => a == b,
+            (Self::Short(short), Self::Full(full)) | (Self::Full(full), Self::Short(short)) => {
+                full[..CONTROL_BYTES] == short[..] && full[CONTROL_BYTES..].iter().all(|&b| b == 0)
+            }
+        }
+    }
+}
+
+impl Eq for ReplayBytes {}
+
+impl core::hash::Hash for ReplayBytes {
+    fn hash<H: core::hash::Hasher>(&self, state: &mut H) {
+        self.with_full(|bytes| bytes.hash(state));
+    }
+}
+
+impl core::fmt::Debug for ReplayBytes {
+    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
+        self.with_full(|bytes| bytes.fmt(f))
     }
 }

