+#[test]
+fn dedup_builders_preserve_replay_data_and_existing_pins_on_refusal() {
+    let base = DedupEntry::new(MessageId::new(7), Endpoint::v4([192, 0, 2, 1], 5683));
+    let ack = [0x60, 0, 0, 7];
+    let short = base.with_replay(&ack);
+    let mut long = [0; DedupEntry::REPLAY_MAX];
+    long[..ack.len()].copy_from_slice(&ack);
+    let equivalent = base.with_replay(&long).with_replay(&ack);
+    assert_eq!(short, equivalent);
+    #[cfg(feature = "std")]
+    {
+        use core::hash::{Hash, Hasher};
+        let hash = |row: DedupEntry| {
+            let mut hash = std::hash::DefaultHasher::new();
+            row.hash(&mut hash);
+            hash.finish()
+        };
+        assert_eq!(hash(short), hash(equivalent));
+        assert_eq!(std::format!("{short:?}"), std::format!("{equivalent:?}"));
+    }
+
+    long[ack.len()] = 1;
+    let shortened = short.with_replay(&long).with_replay(&ack);
+    assert_eq!(shortened.replay(), Some(&ack[..]));
