+        assert_eq!(refused.replay(), None);
+        assert_eq!(refused.with_replay(&ack), row);
+        let cleared = refused.with_replay(&[]);
+        assert_eq!(cleared.replay(), None);
+        assert_eq!(cleared.tx_pin(), None);
